INSERT IGNORE INTO `word_book` VALUES (1, '计算机专业单词', 90, '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word_book` VALUES (6, '四级单词', 150, '2026-04-11 10:35:11', '2026-04-11 10:35:11');
INSERT IGNORE INTO `word` VALUES (8, 1, 'cluster', 'klʌstər', 'n. 群；簇；丛', 3, 'n. 群；簇；丛', 'n. 聚类 [数据挖掘中将相似对象分组的过程]', 'Cluster analysis groups objects based on their similarity.', '聚类分析根据对象的相似性对它们进行分组。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (9, 1, 'medoid', 'ˈmiːdɔɪd', 'n. 中心点', 1, 'n. 中心点', 'n. 中心点 [簇中位置最靠近中心的数据对象]', 'PAM uses real object to represent the cluster.', 'PAM算法使用真实对象（中心点）来代表一个簇。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (10, 1, 'centroid', 'ˈsɛntrɔɪd', 'n. 质心；形心', 1, 'n. 质心；形心', 'n. 质心 [簇中所有对象的平均值]', 'The sum of squared distances is minimized where ci is the centroid of cluster.', '最小化距离平方和，其中ci是簇的质心。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (11, 1, 'outlier', 'ˈaʊtˌlaɪər', 'n. 局外人；离群值', 2, 'n. 局外人；离群值', 'n. 离群点 [在数据集中显著偏离其他数据对象的观察值]', 'Outliers are often viewed as those far away from any cluster.', '离群点通常被视为那些“远离”任何簇的点。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (12, 1, 'scalability', 'ˌskeɪləˈbɪləti', 'n. 可伸缩性', 2, 'n. 可伸缩性', 'n. 可扩展性 [系统在处理海量数据时表现出的适应能力]', 'Scalability is classifying data sets with millions of examples and hundreds of attributes.', '可扩展性是指对具有数百万个示例和数百个属性的数据集进行分类。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (13, 1, 'classification', 'ˌklæsəfɪˈkeɪʃn', 'n. 分类；类别', 3, 'n. 分类；类别', 'n. 分类 [构造一个模型来预测数据标签的过程]', 'Classification is a form of data analysis that extracts models describing important data classes.', '分类是一种提取描述重要数据类的模型的数据分析形式。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (14, 1, 'prediction', 'prɪˈdɪkʃn', 'n. 预言；预测', 3, 'n. 预言；预测', 'n. 预测 [对连续数值函数进行建模以预测未知值的过程]', 'Numeric prediction models continuous-valued functions.', '数值预测对连续值函数进行建模。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (15, 1, 'association', 'əˌsoʊsiˈeɪʃn', 'n. 协会；关联', 3, 'n. 协会；关联', 'n. 关联 [挖掘数据集中频繁出现的项集和关系]', 'Association rules find inherent regularities in data.', '关联规则发现数据中固有的规律。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (16, 1, 'itemset', 'ˈaɪtəmˌsɛt', 'n. 物品集合', 2, 'n. 物品集合', 'n. 项集 [包含一个或多个项的集合]', 'An itemset is a set of one or more items.', '项集是一个或多个项的集合。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (17, 1, 'support', 'səˈpɔrt', 'n. 支持；支撑', 3, 'n. 支持；支撑', 'n. 支持度 [包含特定项集的事务在所有事务中所占的比例]', 'Support is the fraction of transactions that contains the itemset.', '支持度是包含该项集的事务的比例。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (18, 1, 'confidence', 'ˈkɑnfɪdəns', 'n. 信心；信任', 3, 'n. 信心；信任', 'n. 置信度 [在包含项集X的事务中同时包含项集Y的概率]', 'Confidence is the conditional probability that a transaction having X also contains Y.', '置信度是包含X的事务也包含Y的条件概率。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (19, 1, 'apriori', 'ˌeɪpriˈɔri', 'adj. 先验的', 1, 'adj. 先验的', 'n. Apriori算法 [一种利用先验知识发现频繁项集的挖掘算法]', 'Apriori is a candidate generation and test approach.', 'Apriori是一种候选生成和测试方法。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (20, 1, 'entropy', 'ˈɛntrəpi', 'n. 熵', 1, 'n. 熵', 'n. 熵 [信息论中对数据集中不确定性或信息量的度量]', 'Expected information or entropy is needed to classify a tuple in D.', '对D中的元组进行分类需要期望信息或熵。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (21, 1, 'pruning', 'ˈprunɪŋ', 'n. 修剪', 2, 'n. 修剪', 'n. 剪枝 [在决策树中移除过度拟合分支以提高泛化能力的过程]', 'Postpruning removes branches from a fully grown tree.', '后剪枝从完全生长的树中移除分支。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (22, 1, 'overfitting', 'ˌoʊvərˈfɪtɪŋ', 'n. 过度拟合', 2, 'n. 过度拟合', 'n. 过拟合 [模型过度学习训练数据而导致泛化能力下降的现象]', 'Test set is independent of training set to avoid overfitting.', '测试集独立于训练集以避免过拟合。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (23, 1, 'ensemble', 'ɑnˈsɑmbəl', 'n. 全体；合奏', 2, 'n. 全体；合奏', 'n. 集成学习 [结合多个分类器来提高分类准确率的机器学习方法]', 'Ensemble methods use a combination of models to increase accuracy.', '集成方法使用模型的组合来提高准确率。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (24, 1, 'bootstrap', 'ˈbʊtˌstræp', 'n. 靴带；自助法', 2, 'n. 靴带；自助法', 'n. 自助法 [一种从给定训练集中有放回地均匀抽样的方法]', 'Bootstrap samples the given training tuples uniformly with replacement.', '自助法对给定的训练元组进行有放回的均匀抽样。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (25, 1, 'metadata', 'ˈmɛtəˌdeɪtə', 'n. 元数据', 2, 'n. 元数据', 'n. 元数据 [描述数据仓库中数据的数据，如数据的定义和结构]', 'Integrate metadata from different sources into a coherent store.', '将来自不同数据源的元数据集成到一个一致的存储中。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (26, 1, 'schema', 'ˈskimə', 'n. 模式；计划', 2, 'n. 模式；计划', 'n. 模式 [数据库或数据仓库的逻辑结构定义]', 'Schema integration combines data from multiple sources into a coherent store.', '模式集成将来自多个数据源的数据合并到一个连贯的存储中。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (27, 1, 'preprocessing', 'ˌpriˈprɑsɛsɪŋ', 'n. 预处理', 2, 'n. 预处理', 'n. 预处理 [数据挖掘前对原始数据进行清洗和变换等步骤]', 'Data preprocessing includes data cleaning and data integration.', '数据预处理包括数据清理和数据集成。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (28, 1, 'integration', 'ˌɪntɪˈɡreɪʃn', 'n. 结合；整合', 3, 'n. 结合；整合', 'n. 数据集成 [将多个数据源中的数据合并存放在一致的数据存储中]', 'Data integration combines data from multiple sources.', '数据集成合并了来自多个来源的数据。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (29, 1, 'reduction', 'rɪˈdʌkʃn', 'n. 减少；缩减', 3, 'n. 减少；缩减', 'n. 数据归约 [在保持数据原貌前提下缩减数据量的过程]', 'Data reduction obtains a reduced representation of the data set.', '数据归约获得了数据集的缩减表示。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (30, 1, 'discretization', 'dɪˌskritɪˈzeɪʃən', 'n. 离散化', 1, 'n. 离散化', 'n. 离散化 [将连续属性的值域划分为若干区间的过程]', 'Discretization divides the range of a continuous attribute into intervals.', '离散化将连续属性的范围划分为区间。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (31, 1, 'normalization', 'ˌnɔrmələˈzeɪʃn', 'n. 正常化；标准化', 2, 'n. 正常化；标准化', 'n. 规范化 [将属性数据按比例缩放至特定区间的变换方法]', 'Normalization scales data to fall within a smaller specified range.', '规范化缩放数据使其落在一个较小的指定范围内。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (32, 1, 'binning', 'ˈbɪnɪŋ', 'n. 装箱', 2, 'n. 装箱', 'n. 分箱 [通过考察数据的近邻来平滑局部数据噪声的预处理技术]', 'Binning first sorts data and partitions into equal-frequency bins.', '分箱首先对数据进行排序并划分为等频的箱。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
