INSERT IGNORE INTO `word` VALUES (36, 1, 'similarity', 'ˌsɪməˈlɛrɪti', 'n. 相似；类似', 3, 'n. 相似；类似', 'n. 相似度 [度量两个数据对象之间相像程度的数值]', 'Similarity is a numerical measure of how alike two data objects are.', '相似度是两个数据对象相似程度的数值度量。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
