INSERT IGNORE INTO `word` VALUES (39, 1, 'attribute', 'ˈætrəˌbjut', 'n. 属性；特质', 2, 'n. 属性；特质', 'n. 属性 [数据对象的特征或特性，也称为维度或特征]', 'Data objects are described by attributes.', '数据对象由属性来描述。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
