INSERT IGNORE INTO `word` VALUES (42, 1, 'hierarchical', 'ˌhaɪəˈrɑrkɪkl', 'adj. 分层的', 2, 'adj. 分层的', 'adj. 层次的 [按树状结构对数据进行分解的聚类方法]', 'A CF tree stores the clustering features for a hierarchical clustering.', '一棵CF树存储着层次聚类的聚类特征。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (43, 1, 'transaction', 'trænˈzækʃn', 'n. 交易；事务', 3, 'n. 交易；事务', 'n. 事务 [数据库中由一组操作组成的逻辑工作单元，如购物篮数据]', 'The relative support is the probability that a transaction contains the itemset.', '相对支持度是包含该项集的事务的概率。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (44, 1, 'accuracy', 'ˈækjərəsi', 'n. 准确性；精确度', 3, 'n. 准确性；精确度', 'n. 准确率 [分类器正确分类的测试集样本所占的百分比]', 'Accuracy rate is the percentage of test set samples that are correctly classified.', '准确率是被正确分类的测试集样本的百分比。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (45, 1, 'precision', 'prɪˈsɪʒn', 'n. 精度；精密', 2, 'n. 精度；精密', 'n. 精确率 [被分类器标记为正类的样本中实际为正类的百分比]', 'Precision is the exactness of the classifier.', '精确率是分类器的准确性体现。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
