INSERT IGNORE INTO `word` VALUES (47, 1, 'continuous', 'kənˈtɪnjuəs', 'adj. 连续的', 3, 'adj. 连续的', 'adj. 连续的 [指属性可以取实数值并在有限精度内变化]', 'A continuous attribute has real numbers as attribute values.', '连续属性将实数作为属性值。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (48, 1, 'discrete', 'dɪˈskrit', 'adj. 离散的', 2, 'adj. 离散的', 'adj. 离散的 [指属性具有有限或可数无限个值集合]', 'A discrete attribute has only a finite or countably infinite set of values.', '离散属性仅具有有限或可数无限个值的集合。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (49, 1, 'pattern', 'ˈpætərn', 'n. 模式；图案', 3, 'n. 模式；图案', 'n. 模式 [数据中频繁出现的项目集、序列或结构]', 'A frequent pattern occurs frequently in a data set.', '频繁模式是在数据集中频繁出现的模式。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (50, 1, 'frequent', 'ˈfrikwənt', 'adj. 频繁的', 3, 'adj. 频繁的', 'adj. 频繁的 [指支持度大于或等于用户指定阈值的项集或模式]', 'An itemset is frequent if its support is no less than a threshold.', '如果一个项集的支持度不小于某个阈值，则它是频繁的。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (51, 1, 'dimension', 'dɪˈmɛnʃn', 'n. 维度；尺寸', 2, 'n. 维度；尺寸', 'n. 维 [数据仓库中的观察角度或实体的属性集合]', 'A data cube contains multiple dimensions for data analysis.', '数据立方体包含用于数据分析的多个维度。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (52, 1, 'measure', 'ˈmɛʒər', 'n. 测量；度量', 3, 'n. 测量；度量', 'n. 度量 [数据立方体中用于事实评估的定量数值或评估标准]', 'A measure is used for pattern evaluation.', '度量被用于模式评估。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (53, 1, 'noise', 'nɔɪz', 'n. 噪音；喧闹声', 3, 'n. 噪音；喧闹声', 'n. 噪声 [数据测量变量中的随机误差或方差]', 'Data cleaning smooths noisy data and removes noise.', '数据清洗平滑含有噪声的数据并去除噪声。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (54, 1, 'cube', 'kjub', 'n. 立方体', 3, 'n. 立方体', 'n. 数据立方体 [数据仓库中允许多维分析的结构]', 'Data cube aggregation further reduces the size of data.', '数据立方体聚集进一步缩减了数据的大小。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (55, 1, 'naive', 'nɑˈiv', 'adj. 天真的；朴素的', 2, 'adj. 天真的；朴素的', 'adj. 朴素的 [贝叶斯分类器中特征之间条件独立的简化假设]', 'Naive Bayesian prediction requires each conditional probability be non-zero.', '朴素贝叶斯预测要求每个条件概率都非零。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (56, 1, 'bayes', 'beɪz', 'n. 贝叶斯', 1, 'n. 贝叶斯', 'n. 贝叶斯 [指基于贝叶斯定理的统计分类方法]', 'Bayes classification predicts the probability that the hypothesis holds.', '贝叶斯分类预测假设成立的概率。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
INSERT IGNORE INTO `word` VALUES (57, 1, 'pivot', 'ˈpɪvət', 'n. 枢轴；中心点', 2, 'n. 枢轴；中心点', 'n. 旋转 [数据立方体的一种OLAP操作，用于转换多维视图的视角]', 'Pivot is an operation to rotate the data axes in a cube.', '旋转是一种在数据立方体中转动数据轴的操作。', '2026-04-02 16:34:51', '2026-04-02 16:34:51');
