INSERT IGNORE INTO `word` VALUES (892, 6, 'complicated', '/ˈkɑːmplɪkeɪtɪd/', 'adj. 复杂的，难懂的', 1, 'adj. 复杂的，难懂的', NULL, 'The problem is complicated.', '这个问题很复杂。', '2026-04-11 10:35:11', '2026-04-11 10:35:11');
INSERT IGNORE INTO `word` VALUES (893, 6, 'miner', '/ˈmaɪnər/', 'n. 矿工', 2, 'n. 矿工', NULL, 'He is a coal miner.', '他是一名煤矿工人。', '2026-04-11 10:35:11', '2026-04-11 10:35:11');
INSERT IGNORE INTO `word` VALUES (894, 6, 'ripe', '/raɪp/', 'adj. 成熟的', 3, 'adj. 成熟的', NULL, 'The apples are ripe.', '苹果熟了。', '2026-04-11 10:35:11', '2026-04-11 10:35:11');
INSERT IGNORE INTO `word` VALUES (895, 6, 'disclose', '/dɪsˈkloʊz/', 'v. 揭开，揭发，透露', 1, 'v. 揭开，揭发，透露', NULL, 'He refused to disclose the information.', '他拒绝透露信息。', '2026-04-11 10:35:11', '2026-04-11 10:35:11');
INSERT IGNORE INTO `word` VALUES (896, 6, 'quote', '/kwoʊt/', 'v. 引用，引证，报价；n. 引用', 2, 'v. 引用，引证，报价；n. 引用', NULL, 'He quoted a famous poem.', '他引用了一首著名的诗。', '2026-04-11 10:35:11', '2026-04-11 10:35:11');
INSERT IGNORE INTO `word` VALUES (897, 6, 'wolf', '/wʊlf/', 'n. 狼；v. 狼吞虎咽', 3, 'n. 狼；v. 狼吞虎咽', NULL, 'The wolf howls at night.', '狼在夜晚嚎叫。', '2026-04-11 10:35:11', '2026-04-11 10:35:11');
